SELECT ?s ?label ?class ?tsid WHERE {
  ?s a brick:Zone .
  ?s rdfs:label ?label .
  ?s a ?class .
  FILTER (?label IN ("Perimeter_top_ZN_2","DataCenter_bot_ZN_6"))
  OPTIONAL { ?s ref:hasExternalReference ?ext ; ref:hasTimeseriesId ?tsid }
}

SELECT ?s ?label ?class ?tsid WHERE {
  ?s rdfs:label ?label .
  FILTER (regex(?label, "Perimeter_top_ZN_2$"))
  OPTIONAL { ?s a ?class }
  OPTIONAL { ?s ref:hasTimeseriesId ?tsid }
}

SELECT ?s ?label ?pred ?obj WHERE {
  ?s rdfs:label ?label .
  FILTER (?s = ref:Zone_F2_Z07 || regex(str(?s), "Zone_F2_Z07"))
  ?s ?pred ?obj .
}

SELECT ?s ?tsid WHERE {
  ?s a brick:Zone_Air_Temperature_Sensor .
  ?s ref:hasTimeseriesId ?tsid .
  FILTER (regex(str(?s), "Zone_F4_Z03|Zone_F2_Z07"))
}

